'use strict';

function createSelectionModel(records) {
  if (!Array.isArray(records)) {
    throw new TypeError('records must be an array');
  }

  const seen = new Set();
  const entries = records.map((record) => {
    if (record === null || typeof record !== 'object' ||
        typeof record.key !== 'string' || record.key.length === 0 ||
        typeof record.heading !== 'string' || typeof record.detail !== 'string') {
      throw new TypeError('invalid record');
    }
    if (seen.has(record.key)) {
      throw new RangeError('duplicate key');
    }
    seen.add(record.key);
    return {
      key: record.key,
      heading: record.heading,
      detail: record.detail
    };
  });

  let selected = null;

  return {
    toggle(key) {
      if (!seen.has(key)) {
        throw new RangeError('unknown key');
      }
      selected = key;
      return selected;
    },
    activeKey() {
      return selected;
    },
    view() {
      return entries.map((entry) => ({
        key: entry.key,
        heading: entry.heading,
        detail: entry.detail,
        selected: entry.key === selected
      }));
    }
  };
}

module.exports = { createSelectionModel };

