'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['createSelectionModel']);
const { createSelectionModel } = api;

assert.throws(() => createSelectionModel(null), TypeError);
assert.throws(() => createSelectionModel({}), TypeError);
assert.throws(() => createSelectionModel([null]), TypeError);
assert.throws(() => createSelectionModel([{ key: '', heading: 'H', detail: 'D' }]), TypeError);
assert.throws(() => createSelectionModel([{ key: 'a', heading: 1, detail: 'D' }]), TypeError);
assert.throws(() => createSelectionModel([{ key: 'a', heading: 'H', detail: null }]), TypeError);
assert.throws(() => createSelectionModel([
  { key: 'a', heading: 'A', detail: '1' },
  { key: 'a', heading: 'B', detail: '2' }
]), RangeError);

const empty = createSelectionModel([]);
assert.equal(empty.activeKey(), null);
assert.deepEqual(empty.view(), []);
assert.throws(() => empty.toggle('missing'), RangeError);
assert.equal(empty.activeKey(), null);

const records = [
  { key: 'a', heading: 'Alpha', detail: 'First' },
  { key: 'b', heading: 'Beta', detail: 'Second' }
];
const original = structuredClone(records);
const model = createSelectionModel(records);
assert.deepEqual(records, original);
records[0].heading = 'externally changed';
records.push({ key: 'c', heading: 'Gamma', detail: 'Third' });
assert.deepEqual(model.view(), [
  { key: 'a', heading: 'Alpha', detail: 'First', selected: false },
  { key: 'b', heading: 'Beta', detail: 'Second', selected: false }
]);
assert.equal(model.toggle('a'), 'a');
assert.equal(model.activeKey(), 'a');
assert.equal(model.toggle('b'), 'b');
assert.equal(model.activeKey(), 'b');
assert.deepEqual(model.view().map(x => x.selected), [false, true]);
assert.equal(model.toggle('b'), null);
assert.equal(model.activeKey(), null);
model.toggle('a');
assert.throws(() => model.toggle('unknown'), RangeError);
assert.equal(model.activeKey(), 'a');

const firstView = model.view();
const secondView = model.view();
assert.notStrictEqual(firstView, secondView);
assert.notStrictEqual(firstView[0], secondView[0]);
firstView[0].heading = 'mutated';
firstView[0].selected = false;
firstView.splice(1, 1);
assert.deepEqual(model.view(), [
  { key: 'a', heading: 'Alpha', detail: 'First', selected: true },
  { key: 'b', heading: 'Beta', detail: 'Second', selected: false }
]);

